/**
 * Read-only loaders for the reference datasets ("oracles") used to build and re-verify the
 * verbal content packs (src/content/dhatu, src/content/sentences).
 *
 * Nothing here executes code from the datasets — files are only read and parsed.
 * Location: env SAMSKURU_ORACLES (default /home/claude/refs/data), one clone per directory
 * named <owner>_<repo>.
 *
 * Lineages (what is independent of what):
 *   A  ashtadhyayi-com/data  dhatu/…vidyut…  — generated by vidyut-prakriya (Pāṇinian engine, Rust)
 *   B  drdhaval2785/SanskritVerb generatedforms — Dhaval Patel's own Pāṇinian engine (PHP), 2016
 *   C  sanskrit/data sanskrit-heritage-site — Gérard Huet's Sanskrit Heritage engine (OCaml, INRIA)
 *   E  sanskrit/data learnsanskrit.org — hand-entered ending tables (after Kale), CC0
 * A, B and C are three independent implementations (A and B share the dhātupāṭha numbering).
 */
import { existsSync, readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { gunzipSync } from 'node:zlib';
import { devaToSlp1 } from '../../../src/sanskrit/translit';
import type { Lakara, Pada } from '../../../src/content/types';

export const ORACLE_ROOT = process.env.SAMSKURU_ORACLES ?? '/home/claude/refs/data';

export const PATHS = {
  ashDhatupatha: 'ashtadhyayi-com_data/dhatu/data.txt',
  ashKartari: 'ashtadhyayi-com_data/dhatu/dhatuforms_vidyut_shuddha_kartari.txt',
  ashKrut: 'ashtadhyayi-com_data/dhatu/dhatuforms_vidyut_shuddha_krut.txt',
  ashShabda: 'ashtadhyayi-com_data/shabda/data2.txt',
  svForms: 'drdhaval2785_SanskritVerb/generatedforms/verbforms.tar.gz',
  heritageRoots: 'sanskrit_data/sanskrit-heritage-site/roots.csv',
  heritageCslPrs: 'sanskrit-lexicon_csl-inflect/huetdata/extract/huet_conj_tables_prs.txt',
  heritageCslFut: 'sanskrit-lexicon_csl-inflect/huetdata/extract/huet_conj_tables_fut.txt',
  heritageParts: 'sanskrit_data/sanskrit-heritage-site/parts.csv',
  heritageFinal: 'sanskrit_data/sanskrit-heritage-site/final.csv',
  heritageAdverbs: 'sanskrit_data/sanskrit-heritage-site/adverbs.csv',
  lsEndings: 'sanskrit_data/learnsanskrit.org/nominal-endings-inflected.csv',
  lsPronouns: 'sanskrit_data/learnsanskrit.org/pronouns-inflected.csv',
  lsIrregular: 'sanskrit_data/learnsanskrit.org/nouns-irregular-inflected.csv',
  mwPrefixed: 'sanskrit_data/monier-williams/prefixed-roots.csv',
  dcsDir: 'ambuda-org_dcs',
  mwText: 'sanskrit-lexicon_csl-orig/v02/mw/mw.txt',
  apteText: 'sanskrit-lexicon_csl-orig/v02/ap90/ap90.txt',
  vidyutTests: 'ambuda-org_vidyut/vidyut-prakriya/tests',
} as const;

export function oraclePath(rel: string): string {
  return join(ORACLE_ROOT, rel);
}

/** True when every dataset the dhātu generator needs is present. */
export function oraclesAvailable(): boolean {
  return [PATHS.ashDhatupatha, PATHS.ashKartari, PATHS.ashKrut, PATHS.svForms, PATHS.heritageRoots].every((p) => existsSync(oraclePath(p)));
}

function readText(rel: string): string {
  return readFileSync(oraclePath(rel), 'utf8');
}

// ---------------------------------------------------------------------------
// Normalisation shared by all comparisons (SLP1)
// ---------------------------------------------------------------------------

const NASAL_FOR: Record<string, string> = {};
for (const [stops, nasal] of [
  ['kKgG', 'N'],
  ['cCjJ', 'Y'],
  ['wWqQ', 'R'],
  ['tTdD', 'n'],
  ['pPbB', 'm'],
] as const) {
  for (const s of stops) NASAL_FOR[s] = nasal;
}

/**
 * Canonical SLP1 spelling used for comparing sources and for the shipped strings:
 * anusvāra before a stop becomes the class nasal (paṃca → pañca); anusvāra before
 * semivowels, sibilants and h stays; a word-final anusvāra becomes m.
 */
export function normSlp(s: string): string {
  let out = '';
  for (let i = 0; i < s.length; i++) {
    const ch = s.charAt(i);
    if (ch === 'M') {
      const next = s.charAt(i + 1);
      if (next === '') out += 'm';
      else out += NASAL_FOR[next] ?? 'M';
    } else out += ch;
  }
  return out;
}

/** Heritage and SanskritVerb give pre-pausa finals (-s / -r); the packs use pausa forms (visarga). */
export function pausa(s: string): string {
  return s.replace(/[sr]$/, 'H');
}

// ---------------------------------------------------------------------------
// A. ashtadhyayi.com (vidyut-generated)
// ---------------------------------------------------------------------------

export interface AshDhatu {
  baseindex: string;
  dhatu: string;
  aupadeshik: string;
  gana: string;
  pada: string;
  settva: string;
  karma: string;
  artha: string;
  artha_english: string;
  tags: string;
  dhaturoopnandini?: string;
}

export function loadAshDhatupatha(): Map<string, AshDhatu> {
  const json = JSON.parse(readText(PATHS.ashDhatupatha)) as { data: AshDhatu[] };
  const out = new Map<string, AshDhatu>();
  for (const e of json.data) out.set(e.baseindex, e);
  return out;
}

export const ASH_LAKARA_KEY: Record<Lakara, string> = { lat: 'lat', lan: 'lang', lrt: 'lrut', lot: 'lot', vidhilin: 'vidhiling' };

/** baseindex → key (plat, alang …) → 9 cells, each a list of Devanagari alternatives (raw, unfiltered). */
export function loadAshKartari(): Map<string, Map<string, string[][]>> {
  const json = JSON.parse(readText(PATHS.ashKartari)) as Record<string, Record<string, string>>;
  const out = new Map<string, Map<string, string[][]>>();
  for (const [bi, rec] of Object.entries(json)) {
    const m = new Map<string, string[][]>();
    for (const [key, val] of Object.entries(rec)) {
      if (typeof val !== 'string') continue;
      m.set(
        key,
        val.split(';').map((cell) =>
          cell
            .split(',')
            .map((x) => x.trim())
            .filter((x) => x.length > 0),
        ),
      );
    }
    out.set(bi, m);
  }
  return out;
}

export function ashCell(k: Map<string, Map<string, string[][]>>, baseindex: string, lakara: Lakara, pada: Pada, purusha: number, vacana: number): string[] {
  const key = (pada === 'P' ? 'p' : 'a') + ASH_LAKARA_KEY[lakara];
  return k.get(baseindex)?.get(key)?.[(purusha - 1) * 3 + (vacana - 1)] ?? [];
}

export interface KrutCell {
  /** prātipadika (or the indeclinable itself) */
  stem: string;
  m: string;
  f: string;
  n: string;
}

/** baseindex → pratyaya name (Devanagari, e.g. 'क्त्वा') → alternative derivations. */
export function loadAshKrut(): Map<string, Map<string, KrutCell[]>> {
  const json = JSON.parse(readText(PATHS.ashKrut)) as Record<string, Record<string, string>>;
  const out = new Map<string, Map<string, KrutCell[]>>();
  for (const [bi, rec] of Object.entries(json)) {
    const m = new Map<string, KrutCell[]>();
    for (const [key, val] of Object.entries(rec)) {
      if (typeof val !== 'string') continue;
      const cells: KrutCell[] = [];
      for (const deriv of val.split(';')) {
        const [stem = '', mm = '', f = '', n = ''] = deriv.split(',');
        if (stem) cells.push({ stem, m: mm, f, n });
      }
      m.set(key, cells);
    }
    out.set(bi, m);
  }
  return out;
}

export interface AshShabda {
  urlid: string;
  word: string;
  linga: string;
  /** 24 cells: (vibhakti-1)*3 + (vacana-1); each a list of alternatives; sambodhana without the "हे " particle. */
  cells: string[][];
}

export function loadAshShabda(): Map<string, AshShabda> {
  const json = JSON.parse(readText(PATHS.ashShabda)) as { data: { urlid: string; word: string; linga: string; forms: string }[] };
  const out = new Map<string, AshShabda>();
  for (const e of json.data) {
    const cells = e.forms.split(';').map((c) =>
      c
        .split('-')
        .map((x) => x.replace(/^हे\s+/, '').trim())
        .filter((x) => x.length > 0),
    );
    out.set(e.urlid, { urlid: e.urlid, word: e.word, linga: e.linga, cells });
  }
  return out;
}

// ---------------------------------------------------------------------------
// B. SanskritVerb generated forms (XML inside a single-file tar.gz; latin-1, SLP1)
// ---------------------------------------------------------------------------

const SV_LAKARA: Record<string, Lakara> = { law: 'lat', laN: 'lan', lfw: 'lrt', low: 'lot', viDiliN: 'vidhilin' };
const SV_SUFFIX: Record<string, [Pada, number, number]> = {
  tip: ['P', 1, 1],
  tas: ['P', 1, 2],
  Ji: ['P', 1, 3],
  sip: ['P', 2, 1],
  Tas: ['P', 2, 2],
  Ta: ['P', 2, 3],
  mip: ['P', 3, 1],
  vas: ['P', 3, 2],
  mas: ['P', 3, 3],
  ta: ['A', 1, 1],
  AtAm: ['A', 1, 2],
  Ja: ['A', 1, 3],
  TAs: ['A', 2, 1],
  ATAm: ['A', 2, 2],
  Dvam: ['A', 2, 3],
  iw: ['A', 3, 1],
  vahi: ['A', 3, 2],
  mahiN: ['A', 3, 3],
};

export function cellKey(lakara: Lakara, pada: Pada, purusha: number, vacana: number): string {
  return `${lakara}.${pada}.${purusha}.${vacana}`;
}

export interface SvData {
  /**
   * `${gaṇa}|${upadeśa}` → cellKey → set of normalised SLP1 forms. The key is built with
   * {@link svKey}: the file's own `num` attribute is NOT a reliable dhātupāṭha index (its
   * gaṇa prefix is right, the running number often is not), so roots are matched by gaṇa
   * and upadeśa (aupadeśika form with anubandhas). Homonyms with the same gaṇa and upadeśa are merged.
   */
  forms: Map<string, Map<string, Set<string>>>;
  /** the file's `num` attribute → root keys filed under it (used only as a fallback hint) */
  byNum: Map<string, Set<string>>;
}

/** Comparison key for an upadeśa: gaṇa + SLP1 with anunāsika written '!' and pre-consonantal nasals merged. */
export function svKey(gana: number | string, upadeshaSlp: string): string {
  const name = upadeshaSlp.replace(/~/g, '!').replace(/[nMNYR](?=[kKgGcCjJwWqQtTdDpPbBSzs])/g, 'M');
  return `${String(Number(gana)).padStart(2, '0')}|${name}`;
}

/** Reads the first regular file out of a .tar.gz (no code is run; the archive holds one XML file). */
function firstFileOfTarGz(path: string): Buffer {
  const tar = gunzipSync(readFileSync(path));
  const size = parseInt(tar.subarray(124, 136).toString('latin1').replace(/\0/g, '').trim(), 8);
  if (!Number.isFinite(size)) throw new Error('unreadable tar header in ' + path);
  return tar.subarray(512, 512 + size);
}

export function loadSanskritVerb(): SvData {
  const xml = firstFileOfTarGz(oraclePath(PATHS.svForms)).toString('latin1');
  const forms = new Map<string, Map<string, Set<string>>>();
  const byNum = new Map<string, Set<string>>();
  const re = /<f form="([^"]+)"><root name="([^"]+)" num="([^"]+)"\/><(\w+)\/><(\w+)\/><\/f>/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(xml)) !== null) {
    const [, form = '', name = '', num = '', lak = '', suf = ''] = m;
    const lakara = SV_LAKARA[lak];
    const cell = SV_SUFFIX[suf];
    if (!lakara || !cell) continue;
    const rootKey = svKey(num.slice(0, 2), name);
    let nk = byNum.get(num);
    if (!nk) byNum.set(num, (nk = new Set()));
    nk.add(rootKey);
    let byCell = forms.get(rootKey);
    if (!byCell) forms.set(rootKey, (byCell = new Map()));
    const key = cellKey(lakara, cell[0], cell[1], cell[2]);
    let set = byCell.get(key);
    if (!set) byCell.set(key, (set = new Set()));
    set.add(normSlp(form));
  }
  return { forms, byNum };
}

// ---------------------------------------------------------------------------
// C. Sanskrit Heritage (via sanskrit/data CSV)
// ---------------------------------------------------------------------------

const H_MODE: Record<string, Lakara> = { pres: 'lat', ipft: 'lan', sfut: 'lrt', impv: 'lot', opt: 'vidhilin' };
const H_PERSON: Record<string, number> = { '3': 1, '2': 2, '1': 3 };
const H_NUMBER: Record<string, number> = { s: 1, d: 2, p: 3 };
const H_VOICE: Record<string, Pada> = { para: 'P', atma: 'A' };

export interface HeritageData {
  /**
   * root key → cellKey → set of normalised pausa SLP1 forms.
   * Root keys: 'gam', 'BU#1' (primary conjugation); 'taq!caus' (Heritage files most curādi
   * verbs as the causative of the root: ताडयति); 'yuD#1!pass' (Heritage files divādi
   * ātmanepada presents such as युध्यते under the passive, with which they are identical in
   * form — stored with pada 'A').
   */
  forms: Map<string, Map<string, Set<string>>>;
  /** laṭ 3sg form (normalised) + pada → root keys that have it */
  byLat3s: Map<string, string[]>;
}

export function loadHeritageRoots(): HeritageData {
  const forms = new Map<string, Map<string, Set<string>>>();
  const byLat3s = new Map<string, string[]>();
  const lines = readText(PATHS.heritageRoots).split('\n');
  for (let i = 1; i < lines.length; i++) {
    const line = lines[i];
    if (!line) continue;
    const [form = '', root = '', , person = '', number = '', mode = '', voice = '', modification = ''] = line.split(',');
    const mod = modification.trim();
    if (mod !== '' && mod !== 'caus') continue; // desiderative, intensive … are never the taught verb
    const lakara = H_MODE[mode];
    const pada: Pada | undefined = voice === 'pass' ? 'A' : H_VOICE[voice];
    const pu = H_PERSON[person];
    const va = H_NUMBER[number];
    if (!lakara || !pada || !pu || !va) continue;
    if (voice === 'pass' && mod !== '') continue;
    const rootKey = root + (mod === 'caus' ? '!caus' : '') + (voice === 'pass' ? '!pass' : '');
    const f = normSlp(pausa(form));
    let byCell = forms.get(rootKey);
    if (!byCell) forms.set(rootKey, (byCell = new Map()));
    const key = cellKey(lakara, pada, pu, va);
    let set = byCell.get(key);
    if (!set) byCell.set(key, (set = new Set()));
    set.add(f);
    if (lakara === 'lat' && pu === 1 && va === 1) {
      const k = `${f}|${pada}`;
      const arr = byLat3s.get(k) ?? [];
      if (!arr.includes(rootKey)) arr.push(rootKey);
      byLat3s.set(k, arr);
    }
  }
  loadHeritageCsl(forms, byLat3s);
  return { forms, byLat3s };
}

/**
 * Second copy of the Heritage paradigms: csl-inflect's extract of Huet's SL_morph.xml
 * (complete 9-cell tables per root × class × voice; primary conjugation only). Same lineage
 * as roots.csv — it adds coverage (roots.csv lost homographic cells such as laṅ 2pl =
 * ātmanepada 3sg), not independence. Root keys: `csl:${root}:${class}` and, for passive
 * tables, `csl:${root}:Q!pass`; simple-future tables are attached to every class key of the root.
 */
function loadHeritageCsl(forms: Map<string, Map<string, Set<string>>>, byLat3s: Map<string, string[]>): void {
  if (!existsSync(oraclePath(PATHS.heritageCslPrs))) return;
  const TENSE: Record<string, Lakara> = { pr: 'lat', im: 'lan', ip: 'lot', op: 'vidhilin', fut: 'lrt' };
  const parseCells = (body: string): string[][] => {
    const cells: string[][] = [];
    const re = /\(([^)]*)\)|(\S+)/g;
    let m: RegExpExecArray | null;
    while ((m = re.exec(body)) !== null) {
      const raw = m[1] !== undefined ? m[1].split(/\s+/) : (m[2] ?? '').split('/');
      cells.push(raw.flatMap((x) => x.split('/')).filter((x) => x.length > 0));
    }
    return cells;
  };
  const put = (rootKey: string, lakara: Lakara, pada: Pada, cells: string[][]): void => {
    let byCell = forms.get(rootKey);
    if (!byCell) forms.set(rootKey, (byCell = new Map()));
    cells.forEach((cell, i) => {
      const pu = Math.floor(i / 3) + 1;
      const va = (i % 3) + 1;
      const ck = cellKey(lakara, pada, pu, va);
      let set = byCell.get(ck);
      if (!set) byCell.set(ck, (set = new Set()));
      for (const f of cell) {
        const k = normSlp(pausa(f));
        set.add(k);
        if (lakara === 'lat' && i === 0) {
          const idx = `${k}|${pada}`;
          const arr = byLat3s.get(idx) ?? [];
          if (!arr.includes(rootKey)) arr.push(rootKey);
          byLat3s.set(idx, arr);
        }
      }
    });
  };
  const lineRe = /^(\S+) (\S+) (\S+):\[(.*)\]\s*$/;
  const classKeys = new Map<string, Set<string>>();
  for (const line of readText(PATHS.heritageCslPrs).split('\n')) {
    const m = lineRe.exec(line);
    if (!m) continue;
    const [, root = '', tense = '', cv = '', body = ''] = m;
    const lakara = TENSE[tense];
    if (!lakara) continue;
    const cells = parseCells(body);
    if (cells.length !== 9) continue;
    if (cv === '_Q') {
      put(`csl:${root}:Q!pass`, lakara, 'A', cells);
      continue;
    }
    const cm = /^(\d+)([PA])$/.exec(cv);
    if (!cm) continue;
    const rootKey = `csl:${root}:${cm[1]}`;
    put(rootKey, lakara, cm[2] === 'P' ? 'P' : 'A', cells);
    let set = classKeys.get(root);
    if (!set) classKeys.set(root, (set = new Set()));
    set.add(rootKey);
    set.add(`csl:${root}:Q!pass`);
  }
  if (!existsSync(oraclePath(PATHS.heritageCslFut))) return;
  for (const line of readText(PATHS.heritageCslFut).split('\n')) {
    const m = lineRe.exec(line);
    if (!m) continue;
    const [, root = '', tense = '', cv = '', body = ''] = m;
    if (tense !== 'fut' || (cv !== 'P' && cv !== 'A')) continue;
    const cells = parseCells(body);
    if (cells.length !== 9) continue;
    for (const rootKey of classKeys.get(root) ?? []) put(rootKey, 'lrt', cv, cells);
  }
}

export interface HeritageKrt {
  /** root → 'pres.para' | 'pres.atma' | 'past.pass' | 'past.active' | 'fut.pass' → stems (primary only) */
  parts: Map<string, Map<string, Set<string>>>;
  /** root → infinitives */
  infinitive: Map<string, Set<string>>;
  /** root → -tvā gerunds */
  ktva: Map<string, Set<string>>;
  /** root → -ya gerunds (given without prefix) */
  lyap: Map<string, Set<string>>;
}

export function loadHeritageKrt(): HeritageKrt {
  const parts = new Map<string, Map<string, Set<string>>>();
  const add = (m: Map<string, Set<string>>, k: string, v: string): void => {
    let s = m.get(k);
    if (!s) m.set(k, (s = new Set()));
    s.add(v);
  };
  for (const line of readText(PATHS.heritageParts).split('\n').slice(1)) {
    if (!line) continue;
    const [stem = '', root0 = '', , mode = '', voice = '', modification = ''] = line.split(',');
    const mod = modification.trim();
    if (mod !== '' && mod !== 'caus') continue;
    const root = root0 + (mod === 'caus' ? '!caus' : '');
    let byKind = parts.get(root);
    if (!byKind) parts.set(root, (byKind = new Map()));
    add(byKind, `${mode}.${voice}`, normSlp(stem));
  }
  const infinitive = new Map<string, Set<string>>();
  const lyap = new Map<string, Set<string>>();
  for (const line of readText(PATHS.heritageFinal).split('\n').slice(1)) {
    if (!line) continue;
    const [form = '', root0 = '', pos = '', modification = ''] = line.split(',');
    const mod = modification.trim();
    if (mod !== '' && mod !== 'caus') continue;
    const root = root0 + (mod === 'caus' ? '!caus' : '');
    if (pos === 'infinitive') add(infinitive, root, normSlp(form));
    else if (pos === 'gerund') add(lyap, root, normSlp(form));
  }
  const ktva = new Map<string, Set<string>>();
  for (const line of readText(PATHS.heritageAdverbs).split('\n').slice(1)) {
    if (!line) continue;
    const [form = '', root0 = '', pos = '', modification = ''] = line.split(',');
    const mod = modification.trim();
    if (mod !== '' && mod !== 'caus') continue;
    const root = root0 + (mod === 'caus' ? '!caus' : '');
    if (pos === 'gerund') add(ktva, root, normSlp(form));
  }
  return { parts, infinitive, ktva, lyap };
}

/** Devanagari → normalised SLP1 (comparison key). */
export function key(deva: string): string {
  return normSlp(devaToSlp1(deva));
}

// ---------------------------------------------------------------------------
// D. Digital Corpus of Sanskrit (ambuda-org/dcs; CC BY 4.0) — attestation only
// ---------------------------------------------------------------------------

export interface DcsIndex {
  /** surface form (SLP1, anusvāra-normalised) → [lemma, tags, token count] for verbal tokens (pos = v, va, vi) */
  byForm: Map<string, { lemma: string; tags: string; n: number }[]>;
}

/**
 * Loads every verbal token (finite verbs, participles, gerunds/infinitives) of the lemmatised
 * DCS texts. DCS is a human-annotated corpus: a (form, lemma, tag) triple that occurs there is
 * an attestation independent of every form generator. Token forms are sandhied surface forms,
 * so callers must ask for the sandhi shapes they accept.
 */
export function loadDcs(): DcsIndex {
  const byForm = new Map<string, { lemma: string; tags: string; n: number }[]>();
  const dir = oraclePath(PATHS.dcsDir);
  if (!existsSync(dir)) return { byForm };
  for (const name of readdirSync(dir).sort()) {
    if (!name.endsWith('.txt')) continue;
    const text = readFileSync(join(dir, name), 'utf8');
    for (const line of text.split('\n')) {
      if (line.length === 0 || line.charCodeAt(0) === 35) continue;
      const [form = '', lemma = '', tags = ''] = line.split('\t');
      if (!(tags.startsWith('pos=v,') || tags.startsWith('pos=va') || tags.startsWith('pos=vi'))) continue;
      const f = normSlp(form);
      let arr = byForm.get(f);
      if (!arr) byForm.set(f, (arr = []));
      const hit = arr.find((x) => x.lemma === lemma && x.tags === tags);
      if (hit) hit.n++;
      else arr.push({ lemma, tags, n: 1 });
    }
  }
  return { byForm };
}

/**
 * Number of DCS tokens with one of the given surface forms and a tag accepted by `tagOk`;
 * `lemmas` (when given) restricts the lemma.
 */
export function dcsCount(dcs: DcsIndex, forms: string[], lemmas: string[] | null, tagOk: (tags: string) => boolean): number {
  let n = 0;
  const lem = lemmas ? new Set(lemmas) : null;
  for (const f of new Set(forms)) {
    for (const x of dcs.byForm.get(f) ?? []) {
      if ((lem === null || lem.has(x.lemma)) && tagOk(x.tags)) n += x.n;
    }
  }
  return n;
}

// ---------------------------------------------------------------------------
// Dictionary citations (Cologne MW and Apte 1890; CC BY-NC-SA — consulted, never shipped)
// ---------------------------------------------------------------------------

/**
 * All Sanskrit spans of the two dictionaries (SLP1), joined by '|'. Used only to ask "does this
 * long, distinctive word form occur in a headword or a quoted example?" (substring test).
 */
export function loadDictionarySanskrit(): string {
  const parts: string[] = [];
  const ap = oraclePath(PATHS.apteText);
  if (existsSync(ap)) for (const m of readFileSync(ap, 'utf8').matchAll(/\{#([^#]*)#\}/g)) parts.push(normSlp((m[1] ?? '').replace(/<[^>]*>/g, '')));
  const mw = oraclePath(PATHS.mwText);
  if (existsSync(mw)) for (const m of readFileSync(mw, 'utf8').matchAll(/<s>([^<]*)<\/s>/g)) parts.push(normSlp((m[1] ?? '').replace(/[-/\\^]/g, '')));
  return parts.join('|');
}
